ALTER TABLE public.coaching_source_versions DROP CONSTRAINT coaching_source_versions_payload_check;
ALTER TABLE public.coaching_source_versions ADD CONSTRAINT coaching_source_versions_payload_check CHECK (coalesce(
payload->>'review_status'='source_extracted' OR
(source_id='novice-sbd-choice-v1' AND payload->>'id'=source_id AND payload->>'adapter_version'='novice-sbd-choice-v1' AND payload->>'review_status'='internal_product_prototype' AND payload->>'publication_status'='internal_preview') OR
(payload->>'id'=source_id AND payload->>'review_status'='reviewed_product_synthesis' AND payload->'scientific_approval'='false'::jsonb AND
((source_id IN ('mugemuge-sbd-foundation-v1','mugemuge-sbd-trained-v1') AND payload->>'adapter_version'='sbd-evidence-synthesis-v1') OR
(source_id='mugemuge-entry-learning-v2' AND payload->>'adapter_version'='entry-learning-v2'))),false));
CREATE FUNCTION public.coaching_programme_catalog_v6() RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $fn$
SELECT jsonb_build_object('schema_version',3,'catalog_revision',6,'scientific_approval',false,
'items',coalesce(jsonb_agg(jsonb_build_object('source_id',source_id,'version',version,'status',status,'definition',payload) ORDER BY source_id,version),'[]'::jsonb))
FROM public.coaching_source_versions WHERE payload->>'adapter_version' IN
('helms-2018-v1','sbd-template-v1','metd-2021-v1','novice-sbd-choice-v1','petrizzo-2018-v1','per-source-labels-v1','sbd-evidence-synthesis-v1');
$fn$;
CREATE FUNCTION public.coaching_learning_catalog_v1() RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $fn$
SELECT jsonb_build_object('schema_version','entry-catalog-v2','items',coalesce(jsonb_agg(jsonb_build_object('source_id',source_id,'version',version,'status',status,'definition',payload) ORDER BY source_id,version),'[]'::jsonb))
FROM public.coaching_source_versions WHERE payload->>'adapter_version'='entry-learning-v2';
$fn$;
REVOKE ALL ON FUNCTION public.coaching_programme_catalog_v6() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.coaching_learning_catalog_v1() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.coaching_programme_catalog_v6(),public.coaching_learning_catalog_v1() TO anon,authenticated;
INSERT INTO public.coaching_source_versions(source_id,version,payload,status) VALUES ('mugemuge-entry-learning-v2','a3ef347812b78e8577a740a8883a1f32bf9532062229d49462b94050a00ce593','{"id": "mugemuge-entry-learning-v2", "adapter_version": "entry-learning-v2", "kind": "self_guided_education_not_training", "review_status": "reviewed_product_synthesis", "scientific_approval": false, "title": "처음 시작하기 · 동작과 첫 중량", "lessons": [{"id": "squat", "exercise_id": "sit_to_stand", "target_lift": "barbell_back_squat", "title": "의자에서 일어나기", "equipment": ["움직이지 않는 의자", "미끄럽지 않은 바닥"], "steps": ["발바닥이 바닥에 닿는 의자 가장자리에 앉아요.", "몸을 조금 앞으로 기울이고 다리로 천천히 일어나요.", "균형을 잡고 천천히 다시 앉아요."], "practice_reps": 5, "rep_basis": "NHS sit-to-stand example; may stop earlier", "demonstration": {"url": "https://www.nhs.uk/live-well/exercise/strength-exercises/", "section": "Sit-to-stand", "kind": "external_illustrated_instruction"}, "barbell_demonstration": "https://www.nsca.com/education/videos/exercise-technique-high-bar-back-squat/"}, {"id": "push", "exercise_id": "wall_press_up", "target_lift": "barbell_bench_press", "title": "벽 밀기", "equipment": ["움직이지 않는 벽", "미끄럽지 않은 바닥"], "steps": ["벽에서 팔 길이 정도 떨어져 서서 가슴 높이에 손을 대요.", "몸을 곧게 유지하며 팔꿈치를 굽혀 벽 쪽으로 가까워져요.", "천천히 벽을 밀고 돌아와요."], "practice_reps": 5, "rep_basis": "Product single practice set; NHS describes 3 sets of 5–10", "demonstration": {"url": "https://www.nhs.uk/live-well/exercise/strength-exercises/", "section": "Wall press-up", "kind": "external_illustrated_instruction"}, "barbell_demonstration": "https://www.nsca.com/contentassets/48a12160221541acbdc048498d77192d/basics_of_strength_and_conditioning_manual.pdf"}, {"id": "hinge", "exercise_id": "wall_hip_hinge", "target_lift": "barbell_deadlift", "title": "엉덩이 뒤로 보내기", "equipment": ["벽 앞의 빈 공간"], "steps": ["벽을 등지고 서서 무릎을 가볍게 풀어요.", "엉덩이를 뒤로 보내 벽에 가볍게 닿게 해요.", "허리를 억지로 굽히지 않고 편한 범위에서 돌아와요."], "practice_reps": 5, "rep_basis": "Product familiarization example, not source training dose", "demonstration": {"url": "https://www.nsca.com/education/articles/ptq/teaching-resistance-training-movement-patterns/", "section": "Figure 2; linked professional teaching material", "kind": "external_instruction"}, "barbell_demonstration": "https://www.nsca.com/education/videos/exercise-technique-deadlift/"}], "evidence": [{"url": "https://www.nhs.uk/live-well/exercise/strength-exercises/", "kind": "public_health_instruction", "role": "self-directed low-load movement examples"}, {"url": "https://www.nsca.com/education/articles/ptq/teaching-resistance-training-movement-patterns/", "kind": "professional_instruction", "role": "movement learning sequence; self-guided adaptation is a product choice"}, {"url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC12965823/", "kind": "overview_of_reviews", "role": "starting simply and avoiding required failure; not first-load algorithm validation"}], "sequence": ["check_environment", "read_and_view", "practice", "record_control_and_effort", "optional_first_load", "review_next_step"], "practice": {"external_load_kg": 0, "sets": 1, "rest_seconds": null, "basis": "product_introductory_practice_not_strength_dose"}, "first_load": {"optional": true, "reps": 5, "max_trials_per_lift": 3, "load_choice": "user selects an available light training implement; never default a bar to 20 kg", "required": ["lift_instruction_reviewed", "equipment_checked", "safety_support_ready"], "success": "five controlled easy repetitions reported by user; observation only", "next": "record the candidate or choose lighter; no automatic increase", "stop": "pain, uncertain control or inability to use the lightest available implement: stop and seek qualified help", "basis": "product familiarization workflow; not a validated RM test"}, "automatic_mastery": false, "automatic_training_unlock": false, "one_rm_required": false, "limitations": ["앱은 자세를 판정하지 않아요. 불확실하면 중량을 들기 전에 도움을 요청해 주세요.", "가벼운 연습 기록은 1RM이나 5RM 측정값이 아니에요.", "시연은 원 제공기관의 페이지에서 열어요. 영상 재생 환경에 따라 접근이 달라질 수 있어요."]}'::jsonb,'research_preview') ON CONFLICT (source_id,version) DO NOTHING;
INSERT INTO public.coaching_source_versions(source_id,version,payload,status) VALUES ('mugemuge-sbd-foundation-v1','8df1f25ffe7c473746de5bb21575e5fd7454d6cc3fb800e36342f5f536f31ea2','{"id": "mugemuge-sbd-foundation-v1", "adapter_version": "sbd-evidence-synthesis-v1", "title": "SBD 주 2회 · 무게무게 근거 종합", "experience_context": "foundation", "review_status": "reviewed_product_synthesis", "publication_status": "explicit_selection_candidate", "scientific_approval": false, "independent_expert_review": false, "exercises": ["barbell_back_squat", "barbell_bench_press", "barbell_deadlift"], "evidence": {"url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC12965823/", "locator": "2026 ACSM position stand: Table 6, strength, implications", "kind": "overview_of_reviews", "outcome_scope": "general_strength_not_validation_of_this_SBD_programme", "limits": ["Many included participants were inexperienced; not a powerlifting-only review.", "No individual growth curve or effect size is assigned to this product programme."]}, "adaptations": [{"id": "sbd_selection", "basis": "product_policy", "change": "Select SBD for the powerlifting MVP; not a whole-body general fitness claim."}, {"id": "fixed_cycle", "basis": "product_policy", "change": "Eight weeks, 2 nonconsecutive sessions per week, 2 sets of five per lift. This exact combination was not tested by the review."}, {"id": "effort_and_load", "basis": "user_choice", "change": "Known submaximal working loads; stop with repetitions in reserve. No 1RM test or fixed percentage required."}, {"id": "rest", "basis": "user_choice", "change": "Explicit inter-set/inter-exercise rest and warmup; no optimal-rest claim."}, {"id": "progression", "basis": "product_policy", "change": "Review actual sets and choose repeat/increase/decrease. No automatic increment, reset, plateau diagnosis or growth forecast."}], "protocol": {"weeks": 8, "days_per_week": 2, "sessions": [{"week": 1, "day": 1, "exercises": ["barbell_back_squat", "barbell_bench_press", "barbell_deadlift"]}, {"week": 1, "day": 2, "exercises": ["barbell_back_squat", "barbell_bench_press", "barbell_deadlift"]}, {"week": 2, "day": 1, "exercises": ["barbell_back_squat", "barbell_bench_press", "barbell_deadlift"]}, {"week": 2, "day": 2, "exercises": ["barbell_back_squat", "barbell_bench_press", "barbell_deadlift"]}, {"week": 3, "day": 1, "exercises": ["barbell_back_squat", "barbell_bench_press", "barbell_deadlift"]}, {"week": 3, "day": 2, "exercises": ["barbell_back_squat", "barbell_bench_press", "barbell_deadlift"]}, {"week": 4, "day": 1, "exercises": ["barbell_back_squat", "barbell_bench_press", "barbell_deadlift"]}, {"week": 4, "day": 2, "exercises": ["barbell_back_squat", "barbell_bench_press", "barbell_deadlift"]}, {"week": 5, "day": 1, "exercises": ["barbell_back_squat", "barbell_bench_press", "barbell_deadlift"]}, {"week": 5, "day": 2, "exercises": ["barbell_back_squat", "barbell_bench_press", "barbell_deadlift"]}, {"week": 6, "day": 1, "exercises": ["barbell_back_squat", "barbell_bench_press", "barbell_deadlift"]}, {"week": 6, "day": 2, "exercises": ["barbell_back_squat", "barbell_bench_press", "barbell_deadlift"]}, {"week": 7, "day": 1, "exercises": ["barbell_back_squat", "barbell_bench_press", "barbell_deadlift"]}, {"week": 7, "day": 2, "exercises": ["barbell_back_squat", "barbell_bench_press", "barbell_deadlift"]}, {"week": 8, "day": 1, "exercises": ["barbell_back_squat", "barbell_bench_press", "barbell_deadlift"]}, {"week": 8, "day": 2, "exercises": ["barbell_back_squat", "barbell_bench_press", "barbell_deadlift"]}], "working_sets": {"barbell_back_squat": 2, "barbell_bench_press": 2, "barbell_deadlift": 2}, "reps": 5, "automatic_load_adjustment": null, "source_stop_rule": null, "product_stop_rule": "Stop for pain, loss of control or user choice; incomplete records remain unknown.", "effort_guidance": "실패할 때까지 반복하지 않아요. 자세가 흐트러지거나 통증이 생기면 멈춰요.", "duration_basis": "product_review_interval_not_expected_growth_deadline"}, "product_scope": {"adult": true, "independent_sbd": true, "known_working_loads": true, "training_months_min": 0}}'::jsonb,'research_preview') ON CONFLICT (source_id,version) DO NOTHING;
